pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64) -> f64 {
    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();
    let horizon_factor = ((step_index as f64) / (total_jobs as f64)).powf(0.5);

    // Non-linear conditionals
    let cpu_weight = if cpu_norm > 0.8 { 2.5 } else if cpu_norm < 0.3 { 0.75 } else { 1.0 };
    let ram_weight = if ram_norm > 0.8 { 2.5 } else if ram_norm < 0.3 { 0.75 } else { 1.0 };

    // Imbalance penalties
    let imbalance_factor = 1.0 - (imbalance_penalty / ((mean_cpu_residual + mean_ram_residual) * 0.5)).clamp(0.0, 1.0);

    // Horizon-aware placement logic
    let time_factor = if step_index < total_jobs / 2 { 0.8 } else { 1.0 };

    let score = (cpu_norm * cpu_weight + ram_norm * ram_weight) * imbalance_factor - imbalance_penalty * horizon_factor * time_factor;
    score = score * 0.65 + ((cpu_norm * cpu_weight + ram_norm * ram_weight + imbalance_penalty * horizon_factor * time_factor) as f64) * 0.35;
    score = score * 0.90 + (((cpu_norm - ram_norm).abs()) as f64) * 0.10;

    score
}
